// Package storage stores uploaded file contents behind a small driver
// interface. Object keys are always generated by the server (NewKey) and
// validated by every driver (ValidateKey), so user input never reaches a
// filesystem path or bucket key.
package storage

import (
	"context"
	"crypto/rand"
	"encoding/hex"
	"errors"
	"fmt"
	"io"
	"regexp"
	"strings"
	"time"

	"base-admin/server/internal/platform/config"
)

// Errors returned by drivers.
var (
	ErrNotFound   = errors.New("storage: object not found")
	ErrInvalidKey = errors.New("storage: invalid object key")
	ErrExists     = errors.New("storage: object already exists")
)

// Object describes a stored object.
type Object struct {
	Key     string
	Size    int64
	ModTime time.Time
}

// Storage is a blob store. Implementations must be safe for concurrent use.
type Storage interface {
	// Name is the driver name stored with each file ("local" or "s3").
	Name() string
	// Put stores r under key. size is the exact length or -1 if unknown.
	// On error nothing is left behind under key.
	Put(ctx context.Context, key string, r io.Reader, size int64, contentType string) error
	// Open returns the object's contents. The reader also implements
	// io.Seeker for both drivers, which enables HTTP range requests.
	Open(ctx context.Context, key string) (io.ReadCloser, Object, error)
	// Stat returns object metadata or ErrNotFound.
	Stat(ctx context.Context, key string) (Object, error)
	// Delete removes the object; deleting a missing object is not an error.
	Delete(ctx context.Context, key string) error
}

// New builds the configured driver.
func New(cfg config.FileConfig) (Storage, error) {
	switch cfg.Driver {
	case config.FileDriverLocal:
		return NewLocal(cfg.LocalDir)
	case config.FileDriverS3:
		return NewS3(cfg.S3)
	default:
		return nil, fmt.Errorf("storage: unknown driver %q", cfg.Driver)
	}
}

var (
	extPattern     = regexp.MustCompile(`^[a-z0-9]{1,16}$`)
	segmentPattern = regexp.MustCompile(`^[A-Za-z0-9][A-Za-z0-9._-]*$`)
)

// maxKeyLen bounds keys well below filesystem and S3 limits.
const maxKeyLen = 200

// NewKey returns a fresh key "yyyy/mm/dd/<random>.<ext>". ext must be a
// lowercase alphanumeric extension without the dot.
func NewKey(now time.Time, ext string) (string, error) {
	if !extPattern.MatchString(ext) {
		return "", fmt.Errorf("%w: extension %q", ErrInvalidKey, ext)
	}
	b := make([]byte, 16)
	_, _ = rand.Read(b) // crypto/rand.Read never fails (Go 1.24+)
	return now.UTC().Format("2006/01/02") + "/" + hex.EncodeToString(b) + "." + ext, nil
}

// ValidateKey rejects keys that could escape the storage root: absolute
// paths, backslashes, empty, "." or ".." segments and unusual characters.
func ValidateKey(key string) error {
	if key == "" || len(key) > maxKeyLen || strings.HasPrefix(key, "/") || strings.Contains(key, `\`) {
		return fmt.Errorf("%w: %q", ErrInvalidKey, key)
	}
	for seg := range strings.SplitSeq(key, "/") {
		if seg == "." || seg == ".." || strings.Contains(seg, "..") || !segmentPattern.MatchString(seg) {
			return fmt.Errorf("%w: %q", ErrInvalidKey, key)
		}
	}
	return nil
}
